mapper.select:
select from logistics_bill_detail lbd inner join logistics_bill lb on lbd.main_id = lb.id and lb.is_deleted = false where lbd.track_status != 'sign' and lbd.is_deleted = false and lbd.track_no != ''
and lb.order_type in ('B2B','B2C')
and lb.order_type = 'firstMile'
and lbd.track_query_mode = #{query.trackQueryMode}
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
order by lbd.track_time desc

select lbd.id, lbd.track_no, lb.carrier_id as carrierId, lb.tel_number as telNumber from logistics_bill_detail lbd inner join logistics_bill lb on lbd.main_id = lb.id and lb.is_deleted = false where lbd.track_status != 'sign' and lbd.is_deleted = false and lbd.track_no != ''
and lb.order_type in ('B2B','B2C')
and lb.order_type = 'firstMile'
and lbd.track_query_mode = #{query.trackQueryMode}
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
order by lbd.create_time desc

select lbd.id, lbd.track_no, lbd.platform_order_no, lb.carrier_id as carrierId, lb.tel_number as telNumber, lb.channel_id as channelId, lb.transport_no as transportNo, lc.track_query_type as trackQueryType from logistics_bill_detail lbd inner join logistics_bill lb on lbd.main_id = lb.id and lb.is_deleted = false LEFT JOIN logistics_channel lc on lb.channel_id = lc.id and lc.is_deleted = false where lbd.track_status != 'sign' and lbd.is_deleted = false and lbd.track_no != ''
and lb.order_type in ('B2B','B2C')
and lb.order_type = 'firstMile'
and lbd.track_query_mode = #{query.trackQueryMode}
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
order by lbd.create_time desc
